const STORAGE_KEY = 'notepad-content';
const ON_AUTO_SAVED = 'OnAutoSaved';

let instance = null;

class NotepadHandler {
    #dotNetRef;
    #intervalId;
    #dirty = false;

    constructor(dotNetRef) {
        this.#dotNetRef = dotNetRef;
    }

    start(intervalMs) {
        window.addEventListener('beforeunload', this.#onBeforeUnload);

        this.#intervalId = setInterval(async () => {
            await this.#autoSave();
        }, intervalMs);
    }

    #onBeforeUnload = (e) => {
        if (this.#dirty) {
            e.preventDefault();
        }
    };

    async #autoSave() {
        if (!this.#dirty) return;
        const textarea = document.getElementById('notepad-textarea');
        if (!textarea) return;

        const content = textarea.value;
        localStorage.setItem(STORAGE_KEY, content);
        this.#dirty = false;

        try {
            await this.#dotNetRef.invokeMethodAsync(ON_AUTO_SAVED, content);
        } catch { /* circuit disconnected */ }
    }

    markDirty() {
        this.#dirty = true;
    }

    saveNow(content) {
        localStorage.setItem(STORAGE_KEY, content);
        this.#dirty = false;
    }

    load() {
        return localStorage.getItem(STORAGE_KEY);
    }

    clear() {
        localStorage.removeItem(STORAGE_KEY);
        this.#dirty = false;
    }

    dispose() {
        if (this.#intervalId) {
            clearInterval(this.#intervalId);
        }
        window.removeEventListener('beforeunload', this.#onBeforeUnload);
    }
}

export function initialize(dotNetRef, intervalMs) {
    instance = new NotepadHandler(dotNetRef);
    instance.start(intervalMs);
    return instance.load();
}

export function markDirty() {
    instance?.markDirty();
}

export function saveNow(content) {
    instance?.saveNow(content);
}

export function clear() {
    instance?.clear();
}

export function dispose() {
    instance?.dispose();
    instance = null;
}

using Microsoft.JSInterop;

namespace sv_8acaff97c8c14790bb51a628e9e7a6d0.Components.Pages;

public sealed class NotepadInterop : IAsyncDisposable
{
    internal const string ModulePath = "./Components/Pages/Notepad.razor.js";
    internal const string InitMethod = "initialize";
    internal const string MarkDirtyMethod = "markDirty";
    internal const string SaveNowMethod = "saveNow";
    internal const string ClearMethod = "clear";
    internal const string DisposeMethod = "dispose";

    private readonly IJSRuntime _js;
    private IJSObjectReference? _module;

    public NotepadInterop(IJSRuntime js) => _js = js;

    private async ValueTask<IJSObjectReference> GetModuleAsync()
        => _module ??= await _js.InvokeAsync<IJSObjectReference>("import", ModulePath);

    public async ValueTask<string?> InitializeAsync<T>(DotNetObjectReference<T> dotNetRef, int intervalMs) where T : class
    {
        var module = await GetModuleAsync();
        return await module.InvokeAsync<string?>(InitMethod, dotNetRef, intervalMs);
    }

    public async ValueTask MarkDirtyAsync()
    {
        var module = await GetModuleAsync();
        await module.InvokeVoidAsync(MarkDirtyMethod);
    }

