@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea id="notepad-textarea"
          @bind="_content"
          @bind:event="oninput"
          @bind:after="OnContentChanged"
          rows="16"
          placeholder="Type your notes here..."></textarea>

<div class="toolbar">
    <button class="btn btn-primary" @onclick="SaveNow">Save now</button>
    <button class="btn btn-danger" @onclick="Clear">Clear</button>
    <span class="save-status">
        @if (_lastSaved is not null)
        {
            <text>Last saved at @_lastSaved.Value.ToString("HH:mm:ss")</text>
        }
    </span>
</div>

@code {
    private const int AutoSaveIntervalMs = 30_000;

    private string _content = string.Empty;
    private DateTime? _lastSaved;
    private NotepadInterop? _interop;
    private DotNetObjectReference<Notepad>? _dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            _dotNetRef = DotNetObjectReference.Create(this);

            var saved = await _interop.InitializeAsync(_dotNetRef, AutoSaveIntervalMs);
            if (saved is not null)
            {
                _content = saved;
                StateHasChanged();
            }
        }
    }

    private async Task OnContentChanged()
    {
        if (_interop is not null)
        {
            await _interop.MarkDirtyAsync();
        }
    }

    [JSInvokable("OnAutoSaved")]
    public async Task OnAutoSaved(string content)
    {
        await InvokeAsync(() =>
        {
            _content = content;
            _lastSaved = DateTime.Now;
            StateHasChanged();
        });
    }

    private async Task SaveNow()
    {
        if (_interop is not null)
        {
            await _interop.SaveNowAsync(_content);
            _lastSaved = DateTime.Now;
        }
    }

    private async Task Clear()
    {
        if (_interop is not null)
        {
            await _interop.ClearAsync();
            _content = string.Empty;
            _lastSaved = null;
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_interop is not null)
        {
            await _interop.DisposeAsync();
        }

        _dotNetRef?.Dispose();
    }
}

